            if (audit && !spor) mistakes.push({ id: 'sporadic', pts: lost('sporadic') });
            if (n >= 2 && overDed > 0.05) mistakes.push({ id: miami === '100pct' || D > 25 ? 'travel' : 'overded', pts: lost('deductions') });
            if (n >= 2 && underDed > 0.05) mistakes.push({ id: 'underded', pts: lost('deductions') });
            if (audit && !docs) mistakes.push({ id: 'related', pts: lost('related') });
            if (closed && exposure > 0.05 && strat === 'wait') mistakes.push({ id: 'wait', pts: lost('response') });
            if (closed && exposure > 0.05 && strat === 'negotiate') mistakes.push({ id: 'negotiate', pts: lost('response') });
            if (audit && r3.complianceOpt !== 'yes') mistakes.push({ id: 'rental', pts: lost('rental') });
            if (closed && sas) mistakes.push({ id: 'sas', pts: lost('structure') });
            if (closed && !wh) mistakes.push({ id: 'nowithholding', pts: lost('withholding') });
            mistakes.sort(function(a, b) { return b.pts - a.pts; });

            return {
                score: score,
                process: Math.round(process * 10) / 10,
                outcome: Math.round(outcome * 10) / 10,
                tax: Math.round(tax * 10) / 10,
                penaltyRisk: Math.round(Math.max(0, penaltyRisk) * 10) / 10,
                auditRisk: auditRisk,
                sanctions: Math.round(sanctions * 10) / 10,
                auditFound: Math.round(auditFound * 10) / 10,
                exposure: Math.round(exposure * 10) / 10,
                income: I,
                deductions: D,
                omitted: omitted,
                overDed: overDed,
                underDed: underDed,
                mistakes: mistakes.map(function(m) { return m.id; }),
                turningPoint: mistakes.length && mistakes[0].pts >= 3 ? mistakes[0].id : null
            };
        }

        _tier(score) {
            if (score >= 90) return 'expert';
            if (score >= 72) return 'competent';
            return 'beginner';
        }

        _num(v) {
            var lang = (window.vcI18n && window.vcI18n._lang) || document.documentElement.lang || 'es';
            var s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === 'es' ? s.replace('.', ',') : s;
        }

        _feedback(roundIdx, ev, d) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var f = [];
            if (roundIdx === 0) {
                if (ev.omitted <= 1 && ev.income <= 163) f.push(t('r1_feedback_correct'));
                else if (ev.income > 163) f.push(t('r1_feedback_over'));
                else if (ev.omitted <= 6) f.push(t('r1_feedback_close'));
                else f.push(t('r1_feedback_under'));
                f.push(t(d.strategy === '3yr' ? 'r1_dep_correct' : 'r1_dep_wrong'));
                f.push(t(d.complianceOpt === 'yes' ? 'r1_sporadic_correct' : 'r1_sporadic_wrong'));
            } else if (roundIdx === 1) {
                if (ev.overDed > 0.05 && d.strategy !== '100pct') f.push(t('r2_feedback_over'));
                else if (ev.underDed > 0.05 && d.strategy !== '0pct') f.push(t('r2_feedback_conservative'));
                else if (ev.overDed <= 0.05 && ev.underDed <= 0.05) f.push(t('r2_feedback_correct'));
                f.push(t(d.strategy === '50pct' ? 'r2_miami_correct' : (d.strategy === '100pct' ? 'r2_miami_wrong' : 'r2_miami_zero')));
                f.push(t(d.complianceOpt === 'yes' ? 'r2_related_correct' : 'r2_related_wrong'));
            } else if (roundIdx === 2) {
                var s = d.strategy;
                f.push(t(s === 'voluntary' ? 'r3_voluntary_feedback' : (s === 'wait' ? 'r3_wait_feedback' : 'r3_negotiate_feedback')));
                if (ev.exposure > 0.05) f.push(t('r3_exposure').replace('{x}', this._num(ev.exposure)));
                f.push(t(d.complianceOpt === 'yes' ? 'r3_separate_correct' : 'r3_separate_wrong'));
            } else {
                if (ev.auditFound > 0.05) f.push(t('r4_audit_found').replace('{x}', this._num(ev.auditFound)).replace('{y}', this._num(ev.sanctions)));
                f.push(t(d.strategy === 'sas' ? 'r4_sas_feedback' : 'r4_natural_feedback'));
                f.push(t(d.complianceOpt === 'yes' ? 'r4_retention_correct' : 'r4_retention_wrong'));
            }
            return f.join('<br>');
        }

