        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1] || {};
            var ds = last.domainState || {};
            var res = last.results || {};
            var score = (ds.performance && isFinite(ds.performance.overallScore)) ? ds.performance.overallScore : (isFinite(res.complianceScore) ? res.complianceScore : 50);
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var tier = this._tier(score);
            var mistakes = ds.mistakes || [];
            var insights = [];
            if (ds.turningPoint) insights.push(t('turning_' + ds.turningPoint));
            mistakes.forEach(function(m) { if (m !== ds.turningPoint && insights.length < 4) insights.push(t('mistake_' + m)); });
            if (!mistakes.length) insights.push(t('insight_clean'));
            if (insights.length < 3) insights.push(t(score >= 90 ? 'insight_excellent' : (score >= 72 ? 'insight_acceptable' : 'insight_poor')));
            return {
                finalCompliance: score,
                finalPenalty: isFinite(res.penaltyRisk) ? res.penaltyRisk : ds.penaltyRisk,
                finalAuditRisk: isFinite(res.auditRisk) ? res.auditRisk : ds.auditRisk,
                finalTax: isFinite(res.taxLiability) ? res.taxLiability : ds.taxLiability,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                process: ds.subScores ? ds.subScores.process : null,
                outcome: ds.subScores ? ds.subScores.outcome : null,
                performance: tier,
                performanceKey: 'perf_' + tier,
                performanceLabel: t('perf_' + tier),
                turningPoint: ds.turningPoint || null,
                mistakes: mistakes,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var self = this;
            var li = function(x) { return '<li>' + x + '</li>'; };
            var kpi = function(label, value) { return '<div class="tribpn-cm-kpi"><span class="tribpn-cm-kpi-label">' + label + '</span><strong>' + value + '</strong></div>'; };
            var h = '<div class="tribpn-cm">';
            h += '<p class="tribpn-cm-score"><strong>' + Math.round(summary.overallScore || 0) + '</strong> / 100 · <span class="tribpn-cm-tier">' + (summary.performanceLabel || '') + '</span></p>';
            h += '<div class="tribpn-cm-kpis">';
            h += kpi(t('cm_process'), (summary.process != null ? Math.round(summary.process) : '-') + ' / 100');
            h += kpi(t('cm_outcome'), (summary.outcome != null ? Math.round(summary.outcome) : '-') + ' / 100');
            h += kpi(t('tax_liability_label'), 'COP ' + self._num(summary.finalTax || 0) + 'M');
            h += kpi(t('penalty_risk_label'), 'COP ' + self._num(summary.finalPenalty || 0) + 'M');
            h += kpi(t('audit_risk_label'), Math.round(summary.finalAuditRisk || 0) + ' %');
            h += '</div>';
            if (summary.turningPoint) h += '<h4 class="tribpn-cm-h">' + t('cm_turning') + '</h4><p>' + t('turning_' + summary.turningPoint) + '</p>';
            var rest = (summary.insights || []).filter(function(x, i) { return !(summary.turningPoint && i === 0); });
